from dataclasses import dataclass


@dataclass(frozen=True)
class Materiale:
    nome: str
    fy: float
    E: float = 210_000.0
    rho: float = 7850.0

    def fyd(self, gamma=1.05):
        return self.fy / gamma

import csv
import io


def _num(s):
    return float(s.strip().replace(",", "."))


def carica_catalogo(testo):
    righe = csv.DictReader(io.StringIO(testo.strip()), delimiter=";")
    catalogo = {}
    for r in righe:
        if not r["nome"]:
            continue
        catalogo[r["nome"].strip()] = Materiale(r["nome"].strip(), _num(r["fy"]), _num(r["E"]), _num(r["rho"]))
    return catalogo

import math


@dataclass(frozen=True)
class Trazione:
    N: float


@dataclass(frozen=True)
class Flessione:
    M: float
    W: float


@dataclass(frozen=True)
class Taglio:
    V: float
    Av: float


def tensione_ideale(carico, A):
    match carico:
        case Trazione(N=N):
            return N / A
        case Flessione(M=M, W=W):
            return M / W
        case Taglio(V=V, Av=Av):
            return math.sqrt(3) * V / Av
        case _:
            raise TypeError(f"carico non riconosciuto: {carico!r}")

@dataclass(frozen=True, order=True)
class Esito:
    utilizzo: float
    materiale: str

    @property
    def ok(self):
        return self.utilizzo <= 1


def verifica(mat, carico, A, gamma=1.05):
    return Esito(tensione_ideale(carico, A) / mat.fyd(gamma), mat.nome)

def scegli(catalogo, carico, A):
    validi = [m for m in catalogo.values() if verifica(m, carico, A).ok]
    if not validi:
        return None
    return min(validi, key=lambda m: m.fy).nome

