from materiali import Materiale, Trazione, scegli

CAT = {n: Materiale(n, fy) for n, fy in [("S235", 235), ("S275", 275), ("S355", 355)]}


def test_sceglie_il_minimo_sufficiente():
    assert scegli(CAT, Trazione(25_000), 100) == "S275"
    assert scegli(CAT, Trazione(10_000), 100) == "S235"


def test_nessuno():
    assert scegli(CAT, Trazione(1e6), 100) is None
